        this.contextMenuEntry = null;
        this.headerMenuX = ev.clientX;
        this.headerMenuY = ev.clientY;
        this.headerMenuVisible = true;
        this._safeDetect();
        setTimeout(() => {
            const menuEl = this.elRef.nativeElement.querySelector('.context-menu');
            if (!menuEl || !this.headerMenuVisible)
                return;
            const rect = menuEl.getBoundingClientRect();
            const margin = 8;
            let x = ev.clientX;
            let y = ev.clientY;
            if (x + rect.width > window.innerWidth - margin)
                x = Math.max(margin, window.innerWidth - rect.width - margin);
            if (y + rect.height > window.innerHeight - margin)
                y = Math.max(margin, window.innerHeight - rect.height - margin);
            if (x < margin)
                x = margin;
            if (y < margin)
                y = margin;
            if (x !== this.headerMenuX || y !== this.headerMenuY) {
                this.headerMenuX = x;
                this.headerMenuY = y;
                this._safeDetect();
            }
        }, 0);
